@Presieve.isSheafFor_singleton : ∀ {C : Type u_3} [inst : Category.{u_2, u_3} C] {P : Cᵒᵖ ⥤ Type u_1} {X Y : C}
  {f : X ⟶ Y},
  Presieve.IsSheafFor P (Presieve.singleton f) ↔
    ∀ (x : P.obj (Opposite.op X)),
      (∀ {Z : C} (p₁ p₂ : Z ⟶ X),
          p₁ ≫ f = p₂ ≫ f → (ConcreteCategory.hom (P.map p₁.op)) x = (ConcreteCategory.hom (P.map p₂.op)) x) →
        ∃! y, (ConcreteCategory.hom (P.map f.op)) y = x
@Presieve.isSheafFor_iff_generate : ∀ {C : Type u_3} [inst : Category.{u_2, u_3} C] {P : Cᵒᵖ ⥤ Type u_1} {X : C}
  (R : Presieve X), Presieve.IsSheafFor P R ↔ Presieve.IsSheafFor P (Sieve.generate R).arrows
@Equalizer.Presieve.isSheafFor_singleton_iff : ∀ {C : Type u_2} [inst : Category.{u_1, u_2} C] {F : Cᵒᵖ ⥤ Type u_3}
  {X Y : C} {f : X ⟶ Y} (c : Limits.PullbackCone f f) (hc : Limits.IsLimit c),
  Presieve.IsSheafFor F (Presieve.singleton f) ↔ Nonempty (Limits.IsLimit (Limits.Fork.ofι (F.map f.op) ⋯))
EXIT=0
